/* Clear routes from capabilities to evidence and a visitor-controlled enquiry. */
(()=>{
 const tr=(id,en)=>document.documentElement.lang==='en'?en:id;
 const txt=v=>esc(Array.isArray(v)?tr(...v):v);
 const menu=document.querySelector('[data-screen="menu"]');
 menu.classList.add('opportunity-menu');
 const lockup=menu.querySelector('.title-lockup');
 const promise=document.createElement('p');promise.className='hero-promise';lockup.querySelector('.work-descriptor').before(promise);
 const scene=document.createElement('div');scene.className='specialization-scene';scene.innerHTML='<img src="assets/subhi-specializations.webp" width="1672" height="941" fetchpriority="high" alt=""><div class="specialization-controls" role="group"></div><div class="specialization-detail" aria-live="polite"></div><small class="persona-caption"></small>';menu.querySelector('.title-menu').after(scene);
 const roles=[{id:'build',name:'Build',project:'project-13',description:['Website dan aplikasi, dari kebutuhan hingga deployment berbantuan AI.','Websites and applications, from requirements to AI-assisted deployment.']},{id:'create',name:'Create',project:'project-26',description:['Identitas visual, desain konten, dan pengelolaan media sosial.','Visual identity, content design and social media management.']},{id:'strategize',name:'Strategize',project:'project-22',description:['Menghubungkan layanan, audiens, dan komunikasi dalam satu brand.','Connecting services, audiences and communication within one brand.']}];
 let selectedRole='build';
 function roleDraw(){scene.querySelector('img').alt=tr('Representasi tiga aktivitas Muhammad Subhi: desain konten, pembangunan aplikasi, dan perencanaan brand.','Three representations of Muhammad Subhi: content design, application building and brand planning.');scene.querySelector('.specialization-controls').setAttribute('aria-label',tr('Pilih spesialisasi','Choose a specialization'));scene.querySelector('.specialization-controls').innerHTML=[roles[1],roles[0],roles[2]].map(r=>`<button data-specialization="${r.id}" aria-pressed="${r.id===selectedRole}">${r.name}</button>`).join('');const r=roles.find(x=>x.id===selectedRole);scene.querySelector('.specialization-detail').innerHTML=`<p>${txt(r.description)}</p><a href="#portofolio" data-evidence-project="${r.project}">${tr('Lihat karya terkait','Explore related work')} ↗</a>`;scene.querySelector('.persona-caption').textContent=tr('Visual persona berbantuan AI · hasil karya asli ada di Portfolio','AI-assisted persona visual · original work in Portfolio')}
 scene.addEventListener('click',e=>{const b=e.target.closest('[data-specialization]');if(b){selectedRole=b.dataset.specialization;roleDraw();scene.querySelector(`[data-specialization="${selectedRole}"]`).focus({preventScroll:true})}});
 const proof=document.createElement('section');proof.className='project-proof';proof.hidden=true;document.querySelector('[data-screen="portofolio"] .bottom').before(proof);
 let currentProject=projects[active];
 window.renderProjectEvidence=p=>{currentProject=p;proof.hidden=!p?.portfolioEvidence;if(proof.hidden)return;const c=p.portfolioEvidence;proof.innerHTML=`<div class="proof-heading"><div><span class="eyebrow">${tr('MISSION REPORT / STUDI KASUS','MISSION REPORT / CASE STUDY')}</span><h2>${txt(c.thesis)}</h2></div><span class="proof-status">${txt(c.status)}</span></div><p class="proof-intro">${txt(c.intro)}</p><div class="proof-role"><small>${tr('PERAN SAYA','MY ROLE')}</small><p>${txt(c.role)}</p></div><div class="proof-decisions">${c.decisions.map((a,i)=>`<article><span>0${i+1} / ${tr('KEPUTUSAN','DECISION')}</span><h3>${txt(a[0])}</h3><p>${txt(a[1])}</p></article>`).join('')}</div><div class="proof-result"><div><span class="eyebrow">${tr('HASIL YANG TERSEDIA','AVAILABLE DELIVERABLES')}</span><ul>${c.deliverables.map(x=>`<li>${txt(x)}</li>`).join('')}</ul></div><div><span class="eyebrow">${tr('CARA MENINJAU KARYA','HOW TO REVIEW THE WORK')}</span><p>${txt(c.inspect)}</p><div class="proof-actions">${p.live?`<a class="profile-secondary" href="${esc(p.live)}" target="_blank" rel="noopener noreferrer">${p.demoAvailable?tr('Coba demo','Try the demo'):tr('Lihat website','Visit website')} ↗</a>`:''}${p.contentManagement?`<button class="profile-secondary" data-evidence-project="${p.id}">${tr('Lihat konten asli','View original content')} ↑</button>`:''}<a class="profile-primary" href="#about" data-project-enquiry="${esc(p.brand)}">${tr('Diskusikan kebutuhan serupa','Discuss a similar need')} ↗</a></div></div></div><details class="proof-status-note"><summary>${tr('Konteks hasil & status','Deliverables & status context')}</summary><p>${txt(c.boundary)}</p></details>`};
 function openProject(id){const i=projects.findIndex(p=>p.id===id);if(i<0)return;projectQuery='';const q=document.querySelector('#project-search');if(q)q.value='';active=i;filter=projects[i].contentManagement?'social':'all';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});const collection=document.querySelector('.project-collection');if(collection)collection.open=false;if(location.hash==='#portofolio')render();else location.hash='portofolio';requestAnimationFrame(()=>requestAnimationFrame(()=>{(document.querySelector('#content-gallery:not([hidden])')||document.querySelector('.project')).scrollIntoView({block:'start',behavior:'auto'})}))}
 document.addEventListener('click',e=>{const link=e.target.closest('[data-evidence-project]');if(link){e.preventDefault();openProject(link.dataset.evidenceProject)}const q=e.target.closest('[data-project-enquiry]');if(q){intent='project';relatedProject=q.dataset.projectEnquiry;contactDraw()}});
 // One-page professional summary is available without a Drive dependency.
 const cv=document.querySelector('.profile-actions a[download]');
 const fit=document.createElement('article');fit.className='profile-fit';document.querySelector('#character-panel-0').append(fit);
 const work=document.createElement('section');work.className='working-agreement';document.querySelector('[data-screen="profil"]').append(work);
 const hub=document.querySelector('.contact-hub');
 const channels=document.createElement('details');channels.className='alternative-channels';const summary=document.createElement('summary');channels.append(summary);const options=hub.querySelector('.contact-options');options.before(channels);channels.append(options);
 const composer=document.createElement('div');composer.className='enquiry-composer';channels.before(composer);
 let intent='project',relatedProject='';
 const drafts={project:['Halo Subhi, saya ingin mendiskusikan proyek.','Hi Subhi, I would like to discuss a project.'],contract:['Halo Subhi, saya ingin mendiskusikan kontrak kerja dengan lingkup dan periode tertentu.','Hi Subhi, I would like to discuss a fixed-scope or fixed-term engagement.'],job:['Halo Subhi, saya ingin mendiskusikan peluang kerja.','Hi Subhi, I would like to discuss a job opportunity.'],collab:['Halo Subhi, saya ingin mendiskusikan kolaborasi.','Hi Subhi, I would like to discuss a collaboration.']};
 const labels={project:['Proyek freelance','Freelance project'],contract:['Kontrak','Contract'],job:['Peluang kerja','Job opportunity'],collab:['Kolaborasi','Collaboration']};
 let brief='',timing='';
 function updateDraft(){const subject=tr('Diskusi ','Discuss ')+tr(...labels[intent]);const body=[tr(...drafts[intent]),relatedProject?tr('Referensi karya: ','Work reference: ')+relatedProject:'',brief?tr('Kebutuhan / posisi: ','Need / role: ')+brief:'',timing?tr('Waktu / periode: ','Timing / period: ')+timing:''].filter(Boolean).join('\n\n');composer.querySelector('.enquiry-whatsapp').href='https://wa.me/'+portfolioData.profile.whatsapp.replace(/\D/g,'')+'?text='+encodeURIComponent(body);composer.querySelector('.enquiry-email').href='mailto:'+portfolioData.profile.email+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}
 function contactDraw(){composer.innerHTML=`<p class="enquiry-lead">${tr('Pilih tujuan percakapan. Detailnya bisa kita sesuaikan bersama.','Choose the conversation you want to start. We can work out the details together.')}</p><div class="enquiry-intents" role="group" aria-label="${tr('Jenis kesempatan','Opportunity type')}">${Object.keys(labels).map(key=>`<button data-enquiry-intent="${key}" aria-pressed="${intent===key}">${txt(labels[key])}</button>`).join('')}</div>${relatedProject?`<p class="enquiry-reference">${tr('Referensi','Reference')}: ${esc(relatedProject)} <button data-clear-reference aria-label="${tr('Hapus referensi','Clear reference')}">×</button></p>`:''}<label class="enquiry-field" for="enquiry-brief">${intent==='job'?tr('Posisi dan kebutuhan tim','Role and team needs'):tr('Apa yang ingin dikerjakan?','What would you like to work on?')} <small>${tr('(opsional)','(optional)')}</small></label><textarea id="enquiry-brief" rows="3" maxlength="1200" placeholder="${tr('Contoh: website lembaga dan pengelolaan konten Instagram.','Example: an institutional website and Instagram content management.')}">${esc(brief)}</textarea><label class="enquiry-field" for="enquiry-timing">${tr('Rencana waktu / periode','Planned timing / period')} <small>${tr('(opsional)','(optional)')}</small></label><input id="enquiry-timing" maxlength="150" value="${esc(timing)}" placeholder="${tr('Contoh: mulai bulan depan, kontrak tiga bulan.','Example: start next month, three-month contract.')}"><div class="enquiry-actions"><a class="profile-primary enquiry-whatsapp" target="_blank" rel="noopener noreferrer">${tr('Lanjutkan di WhatsApp','Continue on WhatsApp')} ↗</a><a class="profile-secondary enquiry-email">${tr('Lewat email','Use email')} ↗</a></div><p class="enquiry-note">${tr('Pesan dibuka sebagai draf untuk kamu tinjau dan kirim. Isian tidak disimpan di website.','Your message opens as a draft for you to review and send. Entries are not stored on this website.')}</p>`;updateDraft()}
 composer.addEventListener('input',e=>{if(e.target.id==='enquiry-brief')brief=e.target.value;if(e.target.id==='enquiry-timing')timing=e.target.value;updateDraft()});composer.addEventListener('click',e=>{const b=e.target.closest('[data-enquiry-intent]');if(b){intent=b.dataset.enquiryIntent;contactDraw();composer.querySelector(`[data-enquiry-intent="${intent}"]`).focus({preventScroll:true})}if(e.target.closest('[data-clear-reference]')){relatedProject='';contactDraw()}});
 function draw(){
 promise.textContent=tr('Membangun kehadiran digital bisnis dan lembaga, dari brand hingga produk dan konten.','Building a connected digital presence for businesses and institutions, from brand to products and content.');
 menu.querySelector('.title-lockup .eyebrow').textContent=tr('MUHAMMAD SUBHI / PORTOFOLIO PROFESIONAL','MUHAMMAD SUBHI / PROFESSIONAL PORTFOLIO');
 menu.querySelector('.work-descriptor').innerHTML='<span>Web Design</span><span>App Building</span><span>Content Management</span><span>AI Specialist</span>';
 menu.querySelector('.menu-direct-actions a').innerHTML=tr('Lihat karya pilihan','Explore selected work')+' <span aria-hidden="true">↗</span>';
 menu.querySelector('.menu-direct-actions a:last-child').innerHTML=tr('Diskusikan kesempatan','Discuss an opportunity')+' <span aria-hidden="true">↗</span>';
 const gameStart=menu.querySelector('#start');gameStart.innerHTML=tr('Jelajahi menu game','Explore the game menu')+' <span aria-hidden="true">→</span>';
 menu.querySelector('#menu-status').textContent=tr('BUILD · CREATE · STRATEGIZE','BUILD · CREATE · STRATEGIZE');
 fit.innerHTML=`<small>${tr('DI MANA SAYA BISA MEMBANTU','WHERE I CAN HELP')}</small><p>${tr('Bisnis, yayasan, dan institusi berkembang yang membutuhkan website, aplikasi internal, serta komunikasi brand yang saling terhubung.','Growing businesses, foundations and institutions that need connected websites, internal applications and brand communication.')}</p><a href="#portofolio">${tr('Lihat penerapannya di tiga karya pilihan','See the approach in three selected projects')} ↗</a>`;
 work.innerHTML=`<div><span class="eyebrow">${tr('CARA BEKERJA / MISSION FRAMEWORK','WORKING TOGETHER / MISSION FRAMEWORK')}</span><h2>${tr('Kebutuhan jelas. Hasil yang disepakati.','Clear needs. Agreed deliverables.')}</h2><p>${tr('Kerangka berikut menjadi dasar untuk menyepakati penugasan baru. Lingkup, jadwal, revisi, dan dukungan disesuaikan dengan kesepakatan proyek atau tim.','This framework is a starting point for agreeing a new engagement. Scope, schedule, revisions and support depend on the project or team agreement.')}</p></div><ol>${[
 [['Pahami kebutuhan','Understand the need'],['Tujuan, pengguna, kondisi awal, dan prioritas pekerjaan.','Goals, users, starting conditions and work priorities.']],
 [['Tetapkan lingkup','Agree the scope'],['Keluaran, batas pekerjaan, milestone, dan penanggung jawab persetujuan.','Deliverables, scope boundaries, milestones and approval owners.']],
 [['Rancang & bangun','Design & build'],['Struktur, tampilan, konten, atau fitur dikembangkan sesuai kebutuhan. AI membantu proses perencanaan dan produksi.','Structures, interfaces, content or features developed for the need. AI supports planning and production.']],
 [['Tinjau & sesuaikan','Review & refine'],['Kriteria penerimaan, pengujian alur penting, dan putaran revisi ditetapkan bersama.','Agree acceptance criteria, checks for important journeys and revision rounds.']],
 [['Publikasi & serah terima','Publish & hand over'],['Akses, aset, dokumentasi, dan kebutuhan pemeliharaan ditetapkan sesuai penugasan.','Agree access, assets, documentation and maintenance needs for the engagement.']]
 ].map((a,i)=>`<li><span>0${i+1}</span><div><h3>${txt(a[0])}</h3><p>${txt(a[1])}</p></div></li>`).join('')}</ol><div class="agreement-footer"><p>${tr('Untuk peluang kerja: peran, model kerja, alokasi waktu, dan tanggal mulai dibahas sesuai kebutuhan tim.','For job opportunities: role, working arrangement, time allocation and start date are discussed around team needs.')}</p><a class="profile-primary" href="#about">${tr('Mulai percakapan','Start a conversation')} ↗</a></div>`;
 hub.querySelector('h3').textContent=tr('Mari bicarakan kebutuhanmu.','Let’s talk about what you need.');summary.textContent=tr('Kanal lain & profil profesional','Other channels & professional profiles');hub.querySelector(':scope > .cv-hint').textContent=tr('Bogor · proyek, kontrak, kolaborasi, dan peluang kerja remote. Jadwal mulai serta alokasi waktu dibahas bersama.','Bogor · projects, contracts, collaboration and remote job opportunities. Start date and time allocation are discussed together.');
 document.querySelector('#cv-status').textContent=tr('CV ringkas · pengalaman, kemampuan, dan karya pilihan.','Concise CV · experience, capabilities and selected work.');if(cv)cv.href=tr('downloads/muhammad-subhi-cv-id.pdf','downloads/muhammad-subhi-cv-en.pdf');
 roleDraw();contactDraw();window.renderProjectEvidence(currentProject);
 }
 window.addEventListener('languagechange',draw);draw();
})();
